refused_program.body:
set -eu
remote={upstream_remote}
branch={upstream_branch}
file=deps.lock
tmp=$(mktemp -d)
trap 'rm -rf "$tmp"' EXIT
if ! git rev-parse -q --verify MERGE_HEAD >/dev/null 2>&1; then
  git merge --no-ff --no-commit "$remote/$branch" || true
fi
git rev-parse -q --verify MERGE_HEAD >/dev/null
local_rev=$(git rev-parse HEAD)
base=$(git merge-base "$local_rev" "$remote/$branch")
git show "$local_rev:$file" > "$tmp/local.lock"
git show "$base:$file" > "$tmp/base.lock"
git show "$remote/$branch:$file" > "$tmp/upstream.lock"
git diff -U0 "$base" "$local_rev" -- "$file" > "$tmp/local.diff"
cat > "$tmp/add.awk" <<'AWK'
function flush_hunk() {
  if (h == 1 && m == 0 && n > 0) {
    NH = NH + 1
    BS[NH] = start
    BN[NH] = n
    for (j = 1; j <= n; j = j + 1) {
      BL[NH, j] = A[j]
    }
  }
  h = 0
  m = 0
  n = 0
}
BEGIN {
  NH = 0
  nloc = 0
  nup = 0
  while ((getline l < loc) > 0) {
    nloc = nloc + 1
    L[nloc] = l
  }
  close(loc)
  while ((getline l < up) > 0) {
    nup = nup + 1
    U[nup] = l
  }
  close(up)
  h = 0
  m = 0
  n = 0
  start = 0
}
/^@@ / {
  flush_hunk()
  h = 1
  m = 0
  n = 0
  s = $0
  sub(/^@@ -[^ ]+ /, "", s)
  sub(/^[+]/, "", s)
  sub(/,.*/, "", s)
  start = s + 0
  next
}
{
  if (h != 1) next
  c = substr($0, 1, 1)
  if (c == "-") { m = 1 }
  else if (c == "+") { n = n + 1; A[n] = substr($0, 2) }
}
END {
  flush_hunk()
  for (k = 1; k <= NH; k = k + 1) {
    pos = 0
    anchor = ""
    ai = BS[k] + BN[k]
    if (ai <= nloc) anchor = L[ai]
    if (anchor != "") {
      for (i = 1; i <= nup; i = i + 1) {
        if (U[i] == anchor) { pos = i; break }
      }
    }
    if (pos == 0 && BS[k] > 1) {
      anchor = L[BS[k] - 1]
      for (i = 1; i <= nup; i = i + 1) {
        if (U[i] == anchor) { pos = i + 1; break }
      }
    }
    if (pos == 0) pos = nup + 1
    for (i = nup; i >= pos; i = i - 1) {
      U[i + BN[k]] = U[i]
    }
    for (j = 1; j <= BN[k]; j = j + 1) {
      U[pos + j - 1] = BL[k, j]
    }
    nup = nup + BN[k]
  }
  for (i = 1; i <= nup; i = i + 1) {
    print U[i]
  }
}
AWK
awk -v loc="$tmp/local.lock" -v up="$tmp/upstream.lock" -f "$tmp/add.awk" "$tmp/local.diff" > "$tmp/resolved.lock"
cp "$tmp/resolved.lock" "$file"
git add "$file"
GIT_EDITOR=true git commit --no-edit

preconditions.probe:
base=$(git merge-base HEAD refs/remotes/{upstream_remote}/{upstream_branch}) || exit 1
git diff -U0 "$base" HEAD -- deps.lock | awk '
/^@@/ {
  if (h == 1 && m == 0 && n > 0) { found = 1 }
  h = 1
  m = 0
  n = 0
  next
}
{
  if (h != 1) next
  c = substr($0, 1, 1)
  if (c == "-") { m = 1 }
  else if (c == "+") { n = n + 1 }
}
END {
  if (h == 1 && m == 0 && n > 0) { found = 1 }
  if (found == 1) print "ADD"
}
' | grep -q ADD
